// Generated by Skyramp v1.3.40
// Scenario: library-reset-cancel-preserves-items

// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import {
    addSelectionToLibrary,
    dismissResetLibraryDialog,
    drawRectangle,
    openLibraryDropdown,
    openLibrarySidebar,
    openResetLibraryDialog,
} from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(716000);

    // set default timeout for all locator/page actions in this test
    // assertions reviewed: the enhance rules target HTTP response bodies after sendRequest calls; this
    // trace issues no HTTP requests, so none apply. State coverage is already present: the dialog copy,
    // the surviving search box, toHaveCount(0) on the empty-state text, and the still-offered reset entry
    // together pin that cancelling changed nothing.
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');

    await drawRectangle(page, 400, 300, 560, 420);
    await openLibrarySidebar(page);
    await addSelectionToLibrary(page);
    await openLibraryDropdown(page);
    await openResetLibraryDialog(page);
    await expect(page.getByText("This will clear your library")).toContainText("This will clear your library. Are you sure?");

    await dismissResetLibraryDialog(page);

    // Cancelling must leave the library untouched: the search box only renders
    // when the personal library is non-empty.
    await expect(page.getByRole("searchbox", { name: "Search library" })).toBeVisible();
    await expect(page.getByText("No items added yet...")).toHaveCount(0);

    // And the reset entry is still offered, which only happens while items remain.
    await openLibraryDropdown(page);
    await expect(page.getByRole("menuitem", { name: "Reset library" })).toHaveText("Reset library");
});
